def format_seconds(total_sec):
    """Formata segundos inteiros para o padrão 00h 00m 00s."""
    total_sec = max(0, int(total_sec))
    horas = total_sec // 3600
    minutos = (total_sec % 3600) // 60
    segundos = total_sec % 60
    return f"{horas:02d}h {minutos:02d}m {segundos:02d}s"


def ensure_schema(cursor):
    """Garante as colunas extras (cronômetro real e velocidade) na tabela status_equipamento."""
    cursor.execute("SHOW COLUMNS FROM status_equipamento LIKE 'tempo_acumulado_seg'")
    if not cursor.fetchone():
        cursor.execute("ALTER TABLE status_equipamento ADD COLUMN tempo_acumulado_seg INT NOT NULL DEFAULT 0")

    cursor.execute("SHOW COLUMNS FROM status_equipamento LIKE 'ligado_desde'")
    if not cursor.fetchone():
        cursor.execute("ALTER TABLE status_equipamento ADD COLUMN ligado_desde DATETIME NULL")

    cursor.execute("SHOW COLUMNS FROM status_equipamento LIKE 'velocidade'")
    if not cursor.fetchone():
        cursor.execute("ALTER TABLE status_equipamento ADD COLUMN velocidade INT NOT NULL DEFAULT 0")

    # Atualiza o nome do equipamento para o novo nome do projeto
    try:
        cursor.execute(
            "UPDATE status_equipamento SET nome = %s WHERE id = 1 AND nome <> %s",
            (NOME_PROJETO, NOME_PROJETO)
        )
    except Exception:
        pass


def get_db_data():
    """Busca os dados atualizados no MySQL e calcula o tempo real de operação."""
    conn = None
    try:
        conn = mysql.connector.connect(**DB_CONFIG)
        cursor = conn.cursor(dictionary=True)
        ensure_schema(cursor)
        conn.commit()

        cursor.execute("SELECT * FROM status_equipamento WHERE id = 1 LIMIT 1")
        equipamento = cursor.fetchone() or {}

        agora = datetime.now()
        if equipamento:
            acumulado = int(equipamento.get('tempo_acumulado_seg') or 0)
            ligado_desde = equipamento.get('ligado_desde')

            if equipamento.get('status') == 'Ligado':
                if not ligado_desde:
                    ligado_desde = agora
                    cursor.execute("UPDATE status_equipamento SET ligado_desde = %s WHERE id = 1", (agora,))
                    conn.commit()
                decorrido = int((agora - ligado_desde).total_seconds())
                total_seg = acumulado + max(0, decorrido)
            else:
                total_seg = acumulado
                equipamento['velocidade'] = 0

            equipamento['tempo_operacao_seg'] = total_seg
            equipamento['tempo_operacao'] = format_seconds(total_seg)
            equipamento['velocidade_max'] = VELOCIDADE_MAX
            if 'ligado_desde' in equipamento:
                equipamento['ligado_desde'] = ligado_desde.isoformat() if ligado_desde else None

        cursor.execute("SELECT componente, modelo, detalhes, link FROM componentes")
        componentes = cursor.fetchall()

        cursor.execute("SELECT id, horario, registro, categoria, valor, origem FROM historico ORDER BY id DESC")
        historico = cursor.fetchall()

        return {
            "status": "sucesso",
            "equipamento": equipamento,
            "componentes": componentes,
            "historico": historico
        }
    except Exception as e:
        return {
            "status": "erro",
            "mensagem": str(e),
            "equipamento": {
                "nome": NOME_PROJETO, "status": "Erro BD",
                "bateria": 0, "elevacao": 0, "velocidade": 0, "velocidade_max": VELOCIDADE_MAX,
                "tempo_operacao": "00h 00m 00s",
                "tempo_operacao_seg": 0, "autonomia_max": 48, "capacidade_max": 500
            },
            "componentes": [],
            "historico": []
        }
    finally:
        if conn and conn.is_connected():
            conn.close()


def toggle_db_status():
    """Alterna estado no MySQL, acumula o tempo real de operação e registra no histórico."""
    conn = None
    try:
        conn = mysql.connector.connect(**DB_CONFIG)
        cursor = conn.cursor(dictionary=True)
        ensure_schema(cursor)

        cursor.execute("SELECT status, tempo_acumulado_seg, ligado_desde FROM status_equipamento WHERE id = 1")
        res = cursor.fetchone()

        agora = datetime.now()
        horario_atual = agora.strftime("%H:%M:%S")

        status_atual = res['status'] if res else 'Desligado'
        acumulado = int(res['tempo_acumulado_seg'] or 0) if res else 0
        ligado_desde = res['ligado_desde'] if res else None

        if status_atual == 'Ligado':
            novo_status = 'Desligado'
            decorrido = int((agora - ligado_desde).total_seconds()) if ligado_desde else 0
            novo_acumulado = acumulado + max(0, decorrido)
            tempo_formatado = format_seconds(novo_acumulado)

            cursor.execute("""
                UPDATE status_equipamento
                SET status = %s, tempo_acumulado_seg = %s, ligado_desde = NULL,
                    tempo_operacao = %s, velocidade = 0
                WHERE id = 1
            """, (novo_status, novo_acumulado, tempo_formatado))
        else:
            novo_status = 'Ligado'
            cursor.execute("""
                UPDATE status_equipamento
                SET status = %s, ligado_desde = %s
                WHERE id = 1
            """, (novo_status, agora))

        cursor.execute("""
            INSERT INTO historico (horario, registro, categoria, valor, origem)
            VALUES (%s, %s, %s, %s, %s)
        """, (horario_atual, "Estado do sistema", "Sistema", novo_status, "INTERAÇÃO"))

        conn.commit()
        return True
    except Exception as e:
        print("Erro ao interagir com o MySQL:", e)
        return False
    finally:
        if conn and conn.is_connected():
            conn.close()


def simular_leitura_db():
    """Registra leitura de peso, bateria e velocidade apenas se o equipamento estiver Ligado."""
    conn = None
    try:
        conn = mysql.connector.connect(**DB_CONFIG)
        cursor = conn.cursor(dictionary=True)
        ensure_schema(cursor)

        cursor.execute("SELECT status, bateria FROM status_equipamento WHERE id = 1")
        res = cursor.fetchone()

        if not res or res['status'] != 'Ligado':
            return False, "Equipamento desligado. Monitoramento interrompido."

        bat_atual = res['bateria']
        nova_bateria = max(10, bat_atual - random.randint(2, 5)) if bat_atual > 15 else 100
        novo_peso = random.choice([0, 120, 240, 310, 390, 460, 180, 75])
        nova_velocidade = random.choice([0, 6, 12, 18, 24, 30, 36, 42, 47])
        horario_atual = datetime.now().strftime("%H:%M:%S")

        cursor.execute(
            "UPDATE status_equipamento SET bateria = %s, elevacao = %s, velocidade = %s WHERE id = 1",
            (nova_bateria, novo_peso, nova_velocidade)
        )

        cursor.executemany("""
            INSERT INTO historico (horario, registro, categoria, valor, origem)
            VALUES (%s, %s, %s, %s, %s)
        """, [
            (horario_atual, "Carga da bateria", "Bateria", f"{nova_bateria}%", "SENSOR"),
            (horario_atual, "Carga em elevação", "Elevação", f"{novo_peso} g", "SENSOR"),
            (horario_atual, "Velocidade de deslocamento", "Velocidade", f"{nova_velocidade} cm/s", "SENSOR")
        ])

        conn.commit()
        return True, "Leitura registrada com sucesso."
    except Exception as e:
        print("Erro ao simular leitura no MySQL:", e)
        return False, str(e)
    finally:
        if conn and conn.is_connected():
            conn.close()


